(function () {
  "use strict";

  const STORAGE_KEY = "gerador_evidencias_v1";

  // Embedded as base64 (not loaded from logo-pagprime.png at runtime) because
  // jsPDF.addImage() re-fetches an <img src> via XHR to sniff its type, which
  // fails under file:// (no cross-origin XHR between local files).
  const LOGO_DATA_URL = "data:image/png;base64,";
  const LOGO_ASPECT = 320 / 132;

  // ---------- icons (inline SVG, reused in dynamic templates) ----------
  const ICON = {
    chevronUp: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="m18 15-6-6-6 6"/></svg>',
    chevronDown: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="m6 9 6 6 6-6"/></svg>',
    pencil: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"/><path d="m15 5 4 4"/></svg>',
    trash: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18"/><path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><path d="m19 6-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><line x1="10" y1="11" x2="10" y2="17"/><line x1="14" y1="11" x2="14" y2="17"/></svg>',
    x: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>',
    image: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="9" cy="9" r="2"/><path d="m21 15-5-5L5 21"/></svg>',
    inbox: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M22 12h-6l-2 3h-4l-2-3H2"/><path d="M5.45 5.11 2 12v6a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2v-6l-3.45-6.89A2 2 0 0 0 16.76 4H7.24a2 2 0 0 0-1.79 1.11Z"/></svg>',
  };

  // ---------- state ----------
  function defaultState() {
    return { escopo: "", objetivo: "", portais: [], scenarios: [] };
  }
  function emptyScenario() {
    return {
      id: null,
      numero: "",
      status: "",
      funcionalidade: "",
      preCondicao: "",
      procedimento: "",
      resultadoEsperado: "",
      evidencias: [],
    };
  }

  let state = defaultState();
  let draftScenario = emptyScenario();
  let editingId = null;

  // ---------- dom refs ----------
  const $ = (id) => document.getElementById(id);

  const escopoInput = $("escopo");
  const objetivoInput = $("objetivo");
  const portalInput = $("portalInput");
  const btnAddPortal = $("btnAddPortal");
  const portaisChips = $("portaisChips");

  const cenarioFormTitle = $("cenarioFormTitle");
  const numeroInput = $("numero");
  const statusSelect = $("status");
  const funcionalidadeInput = $("funcionalidade");
  const preCondicaoInput = $("preCondicao");
  const procedimentoInput = $("procedimento");
  const resultadoEsperadoInput = $("resultadoEsperado");
  const evidenceZone = $("evidenceZone");
  const thumbs = $("thumbs");

  const btnAddScenario = $("btnAddScenario");
  const btnClearScenario = $("btnClearScenario");
  const btnCancelEdit = $("btnCancelEdit");

  const countScenarios = $("countScenarios");
  const scenarioList = $("scenarioList");

  const btnPdf = $("btnPdf");
  const btnSaveBackup = $("btnSaveBackup");
  const btnLoadBackup = $("btnLoadBackup");
  const fileBackup = $("fileBackup");
  const btnNewReport = $("btnNewReport");

  const preview = $("preview");
  const btnCopy = $("btnCopy");
  const toastEl = $("toast");
  const toastMsgEl = $("toastMsg");

  const confirmOverlay = $("confirmOverlay");
  const confirmTitleEl = $("confirmTitle");
  const confirmMessageEl = $("confirmMessage");
  const confirmOkBtn = $("confirmOkBtn");
  const confirmCancelBtn = $("confirmCancelBtn");

  const btnAddScenarioIconAdd = btnAddScenario.querySelector(".icon-add");
  const btnAddScenarioIconEdit = btnAddScenario.querySelector(".icon-edit");
  const btnAddScenarioLabel = btnAddScenario.querySelector(".btn-label");

  const btnPdfIcon = btnPdf.querySelector(".btn-icon");
  const btnPdfSpinner = btnPdf.querySelector(".btn-spinner");

  // ---------- helpers ----------
  function uid() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  }

  function escapeHtml(str) {
    return String(str ?? "").replace(/[&<>"']/g, (c) => ({
      "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;",
    }[c]));
  }
  function nl2br(str) {
    return escapeHtml(str).replace(/\n/g, "<br>");
  }
  function truncate(str, n) {
    str = str || "";
    return str.length > n ? str.slice(0, n - 1) + "…" : str;
  }
  function dateStamp() {
    const d = new Date();
    const pad = (n) => String(n).padStart(2, "0");
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  }
  function nextNumero() {
    return String(state.scenarios.length + 1).padStart(3, "0");
  }

  let toastTimer = null;
  function toast(msg, isError) {
    toastMsgEl.textContent = msg;
    toastEl.className = "toast show" + (isError ? " error" : "");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => { toastEl.className = "toast"; }, 2800);
  }

  // ---------- confirmation dialog (replaces native confirm()) ----------
  let confirmResolve = null;

  function askConfirm({ title, message, confirmLabel = "Confirmar", cancelLabel = "Cancelar" }) {
    confirmTitleEl.textContent = title;
    confirmMessageEl.textContent = message;
    confirmOkBtn.textContent = confirmLabel;
    confirmCancelBtn.textContent = cancelLabel;
    confirmOverlay.hidden = false;
    requestAnimationFrame(() => confirmOverlay.classList.add("show"));
    confirmOkBtn.focus();
    return new Promise((resolve) => { confirmResolve = resolve; });
  }

  function closeConfirm(result) {
    if (confirmOverlay.hidden) return;
    confirmOverlay.classList.remove("show");
    setTimeout(() => { confirmOverlay.hidden = true; }, 150);
    if (confirmResolve) {
      const resolve = confirmResolve;
      confirmResolve = null;
      resolve(result);
    }
  }

  function readFileAsDataURL(file) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result);
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  }

  // ---------- persistence ----------
  let persistTimer = null;
  function persist() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify({ state, draftScenario, editingId }));
    } catch (e) {
      console.warn("Falha ao salvar rascunho no localStorage:", e);
    }
  }
  function schedulePersist() {
    clearTimeout(persistTimer);
    persistTimer = setTimeout(persist, 300);
  }
  function restore() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return;
      const payload = JSON.parse(raw);
      if (payload.state) state = Object.assign(defaultState(), payload.state);
      if (payload.draftScenario) draftScenario = Object.assign(emptyScenario(), payload.draftScenario);
      if (payload.editingId !== undefined) editingId = payload.editingId;
    } catch (e) {
      console.warn("Falha ao restaurar rascunho:", e);
    }
  }

  // ---------- chips (portais) ----------
  function renderChips(container, arr, onRemove) {
    container.innerHTML = "";
    arr.forEach((val, idx) => {
      const chip = document.createElement("span");
      chip.className = "chip";
      chip.innerHTML = `${escapeHtml(val)} <button type="button" aria-label="remover">${ICON.x}</button>`;
      chip.querySelector("button").addEventListener("click", () => onRemove(idx));
      container.appendChild(chip);
    });
  }

  function addPortal() {
    const val = portalInput.value.trim();
    if (!val) return;
    state.portais.push(val);
    portalInput.value = "";
    persist();
    renderChips(portaisChips, state.portais, removePortal);
    renderPreview();
  }
  function removePortal(idx) {
    state.portais.splice(idx, 1);
    persist();
    renderChips(portaisChips, state.portais, removePortal);
    renderPreview();
  }

  // ---------- evidence handling ----------
  function addEvidence(dataUrl, name) {
    draftScenario.evidencias.push({ id: uid(), dataUrl, name: name || "print.png" });
    persist();
    renderThumbs();
  }
  function removeEvidence(id) {
    draftScenario.evidencias = draftScenario.evidencias.filter((e) => e.id !== id);
    persist();
    renderThumbs();
  }
  function renderThumbs() {
    thumbs.innerHTML = "";
    draftScenario.evidencias.forEach((ev) => {
      const div = document.createElement("div");
      div.className = "thumb";
      div.innerHTML = `<img src="${ev.dataUrl}" alt="evidência"><button type="button" class="thumb-remove" data-id="${ev.id}" aria-label="remover evidência">${ICON.x}</button>`;
      thumbs.appendChild(div);
    });
    thumbs.querySelectorAll(".thumb-remove").forEach((btn) => {
      btn.addEventListener("click", () => removeEvidence(btn.dataset.id));
    });
  }

  // ---------- scenario form ----------
  function populateScenarioForm() {
    if (!editingId && !draftScenario.numero) {
      draftScenario.numero = nextNumero();
    }
    numeroInput.value = draftScenario.numero || "";
    statusSelect.value = draftScenario.status || "";
    funcionalidadeInput.value = draftScenario.funcionalidade || "";
    preCondicaoInput.value = draftScenario.preCondicao || "";
    procedimentoInput.value = draftScenario.procedimento || "";
    resultadoEsperadoInput.value = draftScenario.resultadoEsperado || "";
    renderThumbs();
  }

  function setFormMode(mode) {
    if (mode === "edit") {
      cenarioFormTitle.textContent = "Editar Cenário";
      btnAddScenarioLabel.textContent = "Salvar Alterações";
      btnAddScenarioIconAdd.hidden = true;
      btnAddScenarioIconEdit.hidden = false;
      btnCancelEdit.hidden = false;
    } else {
      cenarioFormTitle.textContent = "Adicionar Cenário";
      btnAddScenarioLabel.textContent = "Adicionar Cenário";
      btnAddScenarioIconAdd.hidden = false;
      btnAddScenarioIconEdit.hidden = true;
      btnCancelEdit.hidden = true;
    }
  }

  function renderScenarioList() {
    scenarioList.innerHTML = "";
    countScenarios.textContent = state.scenarios.length;

    if (state.scenarios.length === 0) {
      scenarioList.innerHTML = `<div class="scenario-empty">${ICON.inbox}<span>Nenhum cenário adicionado ainda.</span></div>`;
      return;
    }

    state.scenarios.forEach((sc, idx) => {
      const badgeClass = sc.status === "Aprovado" ? "badge-green" : sc.status === "Reprovado" ? "badge-red" : "badge-gray";
      const statusClass = sc.status === "Aprovado" ? "status-aprovado" : sc.status === "Reprovado" ? "status-reprovado" : "";
      const row = document.createElement("div");
      row.className = "scenario-item " + statusClass;
      row.innerHTML = `
        <div class="sc-main">
          <span class="sc-numero">${escapeHtml(sc.numero)}</span>
          <span class="sc-func">${escapeHtml(truncate(sc.funcionalidade, 60))}</span>
          <span class="badge ${badgeClass}">${escapeHtml(sc.status || "-")}</span>
          <span class="sc-evid">${ICON.image} ${sc.evidencias.length}</span>
        </div>
        <div class="sc-actions">
          <button class="icon-btn" data-act="up" data-idx="${idx}" title="Mover para cima" ${idx === 0 ? "disabled" : ""}>${ICON.chevronUp}</button>
          <button class="icon-btn" data-act="down" data-idx="${idx}" title="Mover para baixo" ${idx === state.scenarios.length - 1 ? "disabled" : ""}>${ICON.chevronDown}</button>
          <span class="sc-actions-divider"></span>
          <button class="icon-btn" data-act="edit" data-idx="${idx}" title="Editar">${ICON.pencil}</button>
          <button class="icon-btn danger" data-act="del" data-idx="${idx}" title="Remover">${ICON.trash}</button>
        </div>`;
      scenarioList.appendChild(row);
    });

    scenarioList.querySelectorAll("button[data-act]").forEach((btn) => {
      btn.addEventListener("click", async () => {
        const idx = parseInt(btn.dataset.idx, 10);
        const act = btn.dataset.act;
        if (act === "up" && idx > 0) {
          [state.scenarios[idx - 1], state.scenarios[idx]] = [state.scenarios[idx], state.scenarios[idx - 1]];
          persist(); renderScenarioList(); renderPreview();
        } else if (act === "down" && idx < state.scenarios.length - 1) {
          [state.scenarios[idx + 1], state.scenarios[idx]] = [state.scenarios[idx], state.scenarios[idx + 1]];
          persist(); renderScenarioList(); renderPreview();
        } else if (act === "edit") {
          const sc = state.scenarios[idx];
          draftScenario = JSON.parse(JSON.stringify(sc));
          editingId = sc.id;
          populateScenarioForm();
          setFormMode("edit");
          persist();
          $("secCenario").scrollIntoView({ behavior: "smooth", block: "start" });
        } else if (act === "del") {
          const sc = state.scenarios[idx];
          const label = sc.numero ? `o cenário ${sc.numero}` : "este cenário";
          const confirmed = await askConfirm({
            title: "Remover cenário",
            message: `Tem certeza de que deseja remover ${label}? As evidências anexadas também serão excluídas e esta ação não pode ser desfeita.`,
            confirmLabel: "Remover cenário",
            cancelLabel: "Cancelar",
          });
          if (confirmed) {
            state.scenarios.splice(idx, 1);
            persist(); renderScenarioList(); renderPreview();
          }
        }
      });
    });
  }

  function syncDraftFromForm() {
    draftScenario.numero = numeroInput.value.trim();
    draftScenario.status = statusSelect.value;
    draftScenario.funcionalidade = funcionalidadeInput.value.trim();
    draftScenario.preCondicao = preCondicaoInput.value;
    draftScenario.procedimento = procedimentoInput.value;
    draftScenario.resultadoEsperado = resultadoEsperadoInput.value;
  }

  function handleAddScenario() {
    syncDraftFromForm();
    if (!draftScenario.funcionalidade || !draftScenario.status) {
      toast("Preencha ao menos Funcionalidade e Status.", true);
      return;
    }
    if (!draftScenario.numero) draftScenario.numero = nextNumero();

    if (editingId) {
      const idx = state.scenarios.findIndex((s) => s.id === editingId);
      if (idx > -1) state.scenarios[idx] = { ...draftScenario, id: editingId };
      editingId = null;
    } else {
      state.scenarios.push({ ...draftScenario, id: uid() });
    }

    draftScenario = emptyScenario();
    persist();
    populateScenarioForm();
    renderScenarioList();
    renderPreview();
    setFormMode("add");
  }

  function handleClearScenario() {
    draftScenario = emptyScenario();
    editingId = null;
    populateScenarioForm();
    setFormMode("add");
    persist();
  }

  // ---------- preview ----------
  function renderPreview() {
    const portaisTxt = state.portais.join(", ");

    const table1Rows = state.scenarios
      .map((sc) => `<tr><td>${escapeHtml(sc.numero)} - ${escapeHtml(sc.funcionalidade)}</td><td>${escapeHtml(sc.status || "-")}</td></tr>`)
      .join("");

    const table2Rows = state.scenarios
      .map((sc) => {
        const imgs = sc.evidencias.map((ev) => `<img src="${ev.dataUrl}" class="preview-thumb" alt="evidência">`).join(" ");
        const cenarioCell = `
          <strong>Cenário:</strong> ${escapeHtml(sc.numero)} – ${escapeHtml(sc.funcionalidade)}<br>
          <strong>Funcionalidade:</strong> ${escapeHtml(sc.funcionalidade)}<br>
          <strong>Pré-Condição:</strong> ${nl2br(sc.preCondicao)}<br>
          <strong>Procedimento:</strong> ${nl2br(sc.procedimento)}
        `;
        return `<tr>
          <td>${cenarioCell}</td>
          <td>${nl2br(sc.resultadoEsperado)}</td>
          <td>${escapeHtml(sc.status || "-")}</td>
          <td>${imgs || '<span class="no-evid">Sem evidências</span>'}</td>
        </tr>`;
      })
      .join("");

    preview.innerHTML = `
      <p><strong>Resumo do Escopo:</strong><br>${nl2br(state.escopo) || "<em>—</em>"}</p>
      <p><strong>Objetivo do Documento:</strong><br>${nl2br(state.objetivo) || "<em>—</em>"}</p>
      <p><strong>Portal:</strong> ${escapeHtml(portaisTxt) || "<em>—</em>"}</p>

      <table class="ge-table">
        <thead><tr><th>Cenários de testes executados</th><th>Status</th></tr></thead>
        <tbody>${table1Rows || '<tr><td colspan="2"><em>Nenhum cenário adicionado</em></td></tr>'}</tbody>
      </table>

      <table class="ge-table">
        <thead><tr><th>Cenário</th><th>Resultado esperado</th><th>Status</th><th>Evidências</th></tr></thead>
        <tbody>${table2Rows || '<tr><td colspan="4"><em>Nenhum cenário adicionado</em></td></tr>'}</tbody>
      </table>
    `;
  }

  // ---------- copy to clipboard (rich text, works offline) ----------
  function copyPreviewToClipboard() {
    const container = document.createElement("div");
    container.style.position = "fixed";
    container.style.left = "-9999px";
    container.style.top = "0";
    container.setAttribute("contenteditable", "true");
    container.innerHTML = preview.innerHTML;
    document.body.appendChild(container);

    const range = document.createRange();
    range.selectNodeContents(container);
    const sel = window.getSelection();
    sel.removeAllRanges();
    sel.addRange(range);

    let ok = false;
    try { ok = document.execCommand("copy"); } catch (e) { ok = false; }

    sel.removeAllRanges();
    document.body.removeChild(container);

    if (ok) toast("Relatório copiado! Cole no ClickUp.");
    else toast("Não foi possível copiar automaticamente.", true);
  }

  // ---------- pdf ----------
  function setPdfLoading(isLoading) {
    btnPdf.disabled = isLoading;
    btnPdfIcon.hidden = isLoading;
    btnPdfSpinner.hidden = !isLoading;
  }

  async function handleDownloadPdf() {
    if (!window.html2canvas || !window.jspdf || !window.jspdf.jsPDF) {
      toast("Bibliotecas de PDF não carregaram (verifique sua conexão).", true);
      return;
    }

    setPdfLoading(true);
    toast("Gerando PDF...");

    // The preview panel scrolls internally (max-height + overflow-y) so the
    // user can review long reports without the page growing forever. For the
    // export we need the FULL content rendered, not just the visible slice,
    // so the height/overflow constraints are lifted only for the capture.
    const prevMaxHeight = preview.style.maxHeight;
    const prevOverflowY = preview.style.overflowY;
    preview.style.maxHeight = "none";
    preview.style.overflowY = "visible";

    try {
      const canvas = await window.html2canvas(preview, {
        scale: 2,
        useCORS: true,
        backgroundColor: "#ffffff",
        logging: false,
      });

      const { jsPDF } = window.jspdf;
      const doc = new jsPDF("p", "pt", "a4");
      const pageWidth = doc.internal.pageSize.getWidth();
      const pageHeight = doc.internal.pageSize.getHeight();
      const margin = 24;
      const headerHeight = 34;
      const usableWidth = pageWidth - margin * 2;
      const usableHeight = pageHeight - margin * 2 - headerHeight;

      const logoHeight = 16;
      const logoWidth = logoHeight * LOGO_ASPECT;

      function drawPageHeader() {
        doc.addImage(LOGO_DATA_URL, "PNG", pageWidth - margin - logoWidth, margin, logoWidth, logoHeight);
        doc.setDrawColor(226, 232, 240);
        doc.setLineWidth(0.75);
        const lineY = margin + headerHeight - 10;
        doc.line(margin, lineY, pageWidth - margin, lineY);
      }

      const pxPerPt = canvas.width / usableWidth;
      const pageHeightPx = usableHeight * pxPerPt;

      let renderedPx = 0;
      let isFirstPage = true;

      while (renderedPx < canvas.height) {
        const sliceHeightPx = Math.min(pageHeightPx, canvas.height - renderedPx);

        const sliceCanvas = document.createElement("canvas");
        sliceCanvas.width = canvas.width;
        sliceCanvas.height = sliceHeightPx;
        sliceCanvas
          .getContext("2d")
          .drawImage(canvas, 0, renderedPx, canvas.width, sliceHeightPx, 0, 0, canvas.width, sliceHeightPx);

        if (!isFirstPage) doc.addPage();
        drawPageHeader();
        doc.addImage(
          sliceCanvas.toDataURL("image/jpeg", 0.92),
          "JPEG",
          margin,
          margin + headerHeight,
          usableWidth,
          sliceHeightPx / pxPerPt
        );

        renderedPx += sliceHeightPx;
        isFirstPage = false;
      }

      doc.save(`relatorio-evidencias-${dateStamp()}.pdf`);
      toast("PDF gerado com sucesso.");
    } catch (err) {
      console.error("Falha ao gerar PDF:", err);
      toast("Falha ao gerar o PDF.", true);
    } finally {
      preview.style.maxHeight = prevMaxHeight;
      preview.style.overflowY = prevOverflowY;
      setPdfLoading(false);
    }
  }

  // ---------- backup json ----------
  function handleSaveBackup() {
    const payload = { ...state, exportedAt: new Date().toISOString(), version: 1 };
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `relatorio-evidencias-${dateStamp()}.json`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
    toast("Backup salvo.");
  }

  function handleLoadBackupFile(file) {
    const reader = new FileReader();
    reader.onload = () => {
      try {
        const data = JSON.parse(reader.result);
        state = {
          escopo: data.escopo || "",
          objetivo: data.objetivo || "",
          portais: Array.isArray(data.portais) ? data.portais : [],
          scenarios: Array.isArray(data.scenarios) ? data.scenarios : [],
        };
        draftScenario = emptyScenario();
        editingId = null;
        persist();
        renderAll();
        setFormMode("add");
        toast("Backup carregado.");
      } catch (err) {
        toast("Arquivo inválido ou corrompido.", true);
      }
    };
    reader.readAsText(file);
  }

  async function handleNewReport() {
    const confirmed = await askConfirm({
      title: "Iniciar novo relatório",
      message: "As informações gerais, os cenários cadastrados e as evidências anexadas serão apagados permanentemente. Esta ação não pode ser desfeita.",
      confirmLabel: "Apagar tudo",
      cancelLabel: "Cancelar",
    });
    if (confirmed) {
      state = defaultState();
      draftScenario = emptyScenario();
      editingId = null;
      localStorage.removeItem(STORAGE_KEY);
      renderAll();
      setFormMode("add");
      toast("Novo relatório iniciado.");
    }
  }

  // ---------- render all ----------
  function renderAll() {
    escopoInput.value = state.escopo;
    objetivoInput.value = state.objetivo;
    renderChips(portaisChips, state.portais, removePortal);
    renderScenarioList();
    populateScenarioForm();
    renderPreview();
  }

  // ---------- wire events ----------
  function wireEvents() {
    escopoInput.addEventListener("input", () => { state.escopo = escopoInput.value; schedulePersist(); renderPreview(); });
    objetivoInput.addEventListener("input", () => { state.objetivo = objetivoInput.value; schedulePersist(); renderPreview(); });

    btnAddPortal.addEventListener("click", addPortal);
    portalInput.addEventListener("keydown", (e) => { if (e.key === "Enter") { e.preventDefault(); addPortal(); } });


    numeroInput.addEventListener("input", () => { draftScenario.numero = numeroInput.value; schedulePersist(); });
    statusSelect.addEventListener("change", () => { draftScenario.status = statusSelect.value; schedulePersist(); });
    funcionalidadeInput.addEventListener("input", () => { draftScenario.funcionalidade = funcionalidadeInput.value; schedulePersist(); });
    preCondicaoInput.addEventListener("input", () => { draftScenario.preCondicao = preCondicaoInput.value; schedulePersist(); });
    procedimentoInput.addEventListener("input", () => { draftScenario.procedimento = procedimentoInput.value; schedulePersist(); });
    resultadoEsperadoInput.addEventListener("input", () => { draftScenario.resultadoEsperado = resultadoEsperadoInput.value; schedulePersist(); });

    evidenceZone.addEventListener("click", () => evidenceZone.focus());
    evidenceZone.addEventListener("paste", (e) => {
      const items = (e.clipboardData || window.clipboardData).items;
      if (!items) return;
      let found = false;
      for (const item of items) {
        if (item.type && item.type.startsWith("image/")) {
          found = true;
          const file = item.getAsFile();
          readFileAsDataURL(file).then((url) => addEvidence(url, file.name || `print-${Date.now()}.png`));
        }
      }
      if (found) e.preventDefault();
    });
    evidenceZone.addEventListener("dragover", (e) => { e.preventDefault(); evidenceZone.classList.add("dragover"); });
    evidenceZone.addEventListener("dragleave", (e) => { e.preventDefault(); evidenceZone.classList.remove("dragover"); });
    evidenceZone.addEventListener("drop", (e) => {
      e.preventDefault();
      evidenceZone.classList.remove("dragover");
      const files = Array.from(e.dataTransfer.files || []).filter((f) => f.type.startsWith("image/"));
      files.forEach((f) => readFileAsDataURL(f).then((url) => addEvidence(url, f.name)));
    });

    btnAddScenario.addEventListener("click", handleAddScenario);
    btnClearScenario.addEventListener("click", handleClearScenario);
    btnCancelEdit.addEventListener("click", handleClearScenario);

    btnPdf.addEventListener("click", handleDownloadPdf);
    btnSaveBackup.addEventListener("click", handleSaveBackup);
    btnLoadBackup.addEventListener("click", () => fileBackup.click());
    fileBackup.addEventListener("change", (e) => {
      const file = e.target.files[0];
      if (file) handleLoadBackupFile(file);
      fileBackup.value = "";
    });
    btnNewReport.addEventListener("click", handleNewReport);

    btnCopy.addEventListener("click", copyPreviewToClipboard);

    confirmOkBtn.addEventListener("click", () => closeConfirm(true));
    confirmCancelBtn.addEventListener("click", () => closeConfirm(false));
    confirmOverlay.addEventListener("click", (e) => {
      if (e.target === confirmOverlay) closeConfirm(false);
    });
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && !confirmOverlay.hidden) closeConfirm(false);
    });
  }

  // ---------- init ----------
  function init() {
    restore();
    wireEvents();
    renderAll();
    setFormMode(editingId ? "edit" : "add");
  }

  document.addEventListener("DOMContentLoaded", init);
})();
